rows["5:991617622"]="고통스러워요!"
rows["601:24959408"]="엔지니어링은 총기, 장갑, 오토바이, 기계적 다람쥐 등 다양한 유용한, 놀라운, 단순한 이상한 아이템을 만들 수 있게 해 줍니다. 하지만, 이 중 많은 것 은 특수 안경, 벨트, 부츠, 장갑, 담요, 비행기 등이 자신이나 다른 엔지니어들만 사용할 수 있습니다.\010대부분의 원료 공학은 광업에서 수집된 금속이기 때문에 두 직업은 잘 어울립니다.\010많은 창조들은 블랙스미스 해머의 사용이 필요합니다. 이 및 다른 필요한 재료, 예를 들어 총 주식 또는 유동, 무역 또는 엔지니어링 판매자로부터 구입할 수 있습니다."
rows["602:18375583"]="필사자 여러분, 여러분은 저를 죽음보다 더 나쁜 운명에서 구해 주셨어요. 그들의 기구에 남겨둔 리치 왕의 마법사들은 결국 내 의지를 깨고, 고통스러운 불생의 영원으로 저를 저해했을 것입니다. 여러분 앞에 그렇게 운이 좋지 않은 사람이 있습니다. 한때 자랑스러운 마리고스의 배우자인 시드라고사.$B$B네일타리온의 배신 후 치명적으로 부상당하고 아이스 크로언의 눈 속에서 홀로 죽게 된 그녀는 순수한 증오의 존재로 존재하고 있지만 악의의 그 층 아래에는 여전히 용 여왕의 귀한 정신이 남아 있습니다."
rows["60:1004552573"]="네놈의 돈을 뺏을까 목숨을 앗아갈까! 너의 목숨이 더 좋겠구나..."
rows["60:1023827869"]="난 이 오그르들을 지쳐야 돼"
rows["60:1024767993"]="* 경고!* 한 가지 의 맞춤 전문 분야 를 선택 할 수 있습니다."
rows["60:103111497"]="앞쪽의 불꽃차례가 나쁜거야 조심해"
rows["60:1031214943"]="전사들이로군, 네가 그보다 더 강하게 내려 칠 수 있다는 걸 알고 있다! 어디 한번 제대로 쳐 보란 말이다!"
rows["60:1042007177"]="죽었어, 모두 죽었어! 적어도 난 임금도 내지 않아도 돼."
rows["60:1044779216"]="우리는 협곡을 따라 달아 내려가 돌이 떨어지지 않도록 조심했습니다."
rows["60:1045893631"]="우리는 진주 마을 위에 있는 언덕에 작은 캠프를 세웠습니다."
rows["60:1050142489"]="우리 아이가 태어났습니다. 소녀입니다. 아름다운 아기입니다."
rows["60:1051306331"]="잘했어, 괜찮은 상태인 것 같아"
rows["60:1052685136"]="가슴에 있는 고통은 곧 사라질 거야 다시는 돌아오지 않을거야"
rows["60:1056871313"]="호드가 서부불꽃 공성 작업장을 장악했습니다!"
rows["60:1061922861"]="내 아버지, 죽음의 날개는 아제로스 전체를 파괴하려고 시도했습니다."
rows["60:1063846194"]="놈들을 즐겁게 해 줘라. 리치 왕께서 보고 계신다!"
rows["60:1066108386"]="내 목숨을 구해줘서 고마워요"
rows["60:1071492684"]="마침내 적들이 도착했습니다!"
rows["60:1079058987"]="난 얼라이언스에서 왔고 우리는 동맹국이 되고 싶지만 적이 아닙니다."
rows["60:1080224657"]="토슬리 역 호네에 오신 것을 환영합니다."
rows["60:1085479937"]="폭발적인 소방장치!"
rows["60:109333716"]="내가 너를 훈련시킬 수 없어 교실 코치와 얘기해"
rows["60:1095829311"]="이렇게 많은 파괴, 죽음이... 이 일이 멈출 수 있을까?"
rows["60:1103299331"]="그러지 마, 굴란!"
rows["60:1104260723"]="어쩌면 내 자신의 의심과 두려움에 너무 많이 감싸여있었을지도 모릅니다."
rows["60:1105239730"]="전투가 끝났고 다로우셔의 사람들은 구출됐습니다."
rows["60:1106439601"]="안도로프는 당신을 비참하게 쳐다보고 있습니다.$B$B피를 흘리면 죽여줄 수 있어"
rows["60:1107275325"]="우린 와일드햄어 끝까지 싸워야 돼"
rows["60:1117365342"]="형제자매, 무기를 들고! 그들은 땅을 파괴하고 있습니다!"
rows["60:1121859743"]="당신의 절을 믿으세요. 당신이 가장 필요할 때 당신을 위해있을 것입니다."
rows["60:1122163227"]="이 독성 물질을 당신 같은 멍청이에게 옮길 필요가 있어요!"
rows["60:112573240"]="반복으로 능숙할 수 없는 것은 없습니다."
rows["60:1131361769"]="%s 빛의 심판이 그 위에 임하는 동안 고통으로 뒤로 물러나!"
rows["60:1131795332"]="난 이 일을 할 수 없을거야 얼라이언스 똥이 내 상을 훔쳐갔어"
rows["60:113241763"]="제임스 할로우의 친절으로 타롱브랑크 글레이드까지 갈게요"
rows["60:1132510901"]="저는 사냥꾼들을 우리 조상들의 방법과 전통에 따라 훈련합니다."
rows["60:1136155627"]="일부 잔해 밑에는 치료사들이 있어요"
rows["60:1138881108"]="며칠 동안 여기 있었지 날 희생하려던 거야"
rows["60:1139107208"]="고마워, 친구. 끔찍한 운명에서 구해줬어."
rows["60:1142113539"]="내가 예쁘다고 부르는 사람은 누구나 무료 맥주를 받을 수 있다는 규칙이 있어요."
rows["60:1149488232"]="외계인, 당신은 돌고래 방식에 대해 아무것도 몰라요"
rows["60:1150028633"]="다시 우리한테 놔두지 마, 반 미치한 코크론!"
rows["60:1150598931"]="복수는 내 몫이 될거야."
rows["60:1151995795"]="넌 아제로스의 구주인 척 하는 거야"
rows["60:1156081080"]="무슨 일이라도 있습니까, 불똥 님? 모이라고 하신 이유가 뭡니까?"
rows["60:1156691136"]=" ⁇ 을 원하시나요?"
rows["60:1158606564"]="넌 아직 살아 있어! 좋은데, 도시의 거리에서 혼란이 있습니다."
rows["60:1170038589"]="저기 무슨 일이 일어나고 있어요?"
rows["60:117291974"]="너무 가까이 오지 마 마야, 머리가 찢어질 거야!"
rows["60:1177033051"]="우리는 그들나 그들의 신들보다 훨씬 더 큰 힘을 섬기죠."
rows["60:1177139509"]="나는 널 던져 넣는 광경을 지켜보면서 웃기나 할 테니까."
rows["60:1190910954"]="네, 너무 약해 더 많은 치료가 필요해 다시 시도해봐"
rows["60:119313155"]="상처와 때림이 있을지도 모르지만 내 안에 증오가 끓어오르고 있습니다."
rows["60:1196222556"]="천상의 토너먼트에 참가하기 위해서는 어떤 조건이 있어야 할까요?"
rows["60:1196305553"]="저건 뭐였지?"
