rows["60:1217012059"]="그들이 부족한 지능을 그들은 잔인하게 보상합니다!"
rows["60:1218882785"]="곰은 조용하고 인내심을 가지고 당신을 쳐다보고 있지만 아무 말도 하지 않습니다."
rows["60:1218950184"]="호드가 동부불꽃 공성 작업장을 장악했습니다!"
rows["60:1237085012"]="이 침입자들이 우리의 일을 해소하기 전에 막아야 합니다!"
rows["60:1245376162"]="의무가 부르죠? 먼저, 벨은..."
rows["60:1248050153"]="그레이먼 장로는 마지막에 스톰 피크스에서 K3를 방문하는 동안 목격되었습니다."
rows["60:1249771890"]="내 모습을 봐, 진짜 오크가 이런 모습이야!"
rows["60:1251191007"]="당신 같은 사람들이 멸망할 수 있는 영혼들을 마주치 마, 마술가!"
rows["60:1259869080"]="당신 말이 저를 그렇게 힘을 포기하도록 설득할 수 없습니다!"
rows["60:1261669372"]="메이, 여기 소금을 찾을 수 있는 곳도 알겠나?"
