rows["60:1275545869"]="아슈토템 사장님, 제가 준 지표가 잘못됐습니다."
rows["60:1276725455"]="쉐도파인은 외부의 도움이 필요 없어!"
rows["60:1280427610"]="실크 방패를 깨고"
rows["60:1286373902"]="도전을 피하는 것보다 직면하는 것이 낫습니다."
rows["60:1290076833"]="가속히 가, 삐걱거리는 놈들..."
rows["60:1294890230"]="이건 당신들의 일이 아닙니다. $p내가 떠날 수 있게 해 줄게"
rows["60:1310582283"]="영혼이 없는, 술도 없는, 문화가 없는 방랑자!"
rows["60:1312470414"]="죽은 놈들이 한 조각으로 살아남았다고 생각하십니까?"
rows["60:1318969782"]="하늘이 어두워지고, 천체는 불안해!"
rows["60:1319000582"]="이프-이프 대장이 앞으로 공격할 겁니다!"
rows["60:1322007398"]="영혼들을 부드럽게 하라, 이들은 죽은 자들의 방이다!"
rows["60:1322379281"]="너희를 쫓아내고 고블린을 고용해 버릴까! 날 실망시키지 마라!"
rows["60:132449608"]="안녕, 친구 평생 거래에 대해 궁금해?"
rows["60:1330524411"]="엄마 말이 맞았어요. 나는 절대 아르헨티나 십자군 전쟁에 참가하지 않을 겁니다."
rows["60:1332989552"]="잘했어, 용감한 계급을 받을 자격이 있어"
rows["60:1342696748"]="모든 고원은 드래곤마우에 속해 있습니다. 이 구멍까지요!"
rows["60:1343038346"]="어떤 바보가 예고 없이 그녀의 영주권에 진입할 용기가 있을까요?"
rows["60:1343779709"]="애송이들! 날 이길 수 있을 거라 생각 마라! 난 사람 죽이는 게 직업이다."
rows["60:1347032041"]="그들은 내가 축복받은 사람이라고 말합니다. 새로운 시대에 울릴 전신입니다."
rows["60:1348651767"]="걱정 마, 우린 너들을 보호해!"
rows["60:1349532708"]="난 여기 떨어질 수 없어"
