rows["60:1399050068"]="강력한 투어, 산에서 떨어지지 마!"
rows["60:1399198722"]="%s 당신을 냄새가 나기 전에 당신의 방향으로 거무고 있습니다."
rows["60:1399732215"]="내가 믿는 것 때문에 제 자신을 희생하는 것이 영광입니다."
rows["60:1406600275"]="잔해들을 찾기 위해서는 빨리 노력해야 합니다."
rows["60:1420436497"]="우리 세계의 미래에 대한 희망은 훨씬 더 우울해졌습니다."
rows["60:1421845647"]="이것이 네놈들의 미래다. 아무것도 남은 건 없지..."
rows["60:1423978365"]="여기 살을 줄여야 돼, 회사를 줄이고 있어!"
rows["60:1424811276"]="부모님은 내가 그들을 알기 전에 살해당했고 배신당했습니다!"
rows["60:1426681993"]="이럴 수가! 그만! 제발 그만! 내가 졌다! 내가 졌어!"
rows["60:1427514207"]="1년 중 이때는 우리의 동맹인 포세이큰에게 매우 의미가 깊은 때랍니다."
rows["60:1429611333"]="동맹의 도움으로 %s은 다시 살아납니다."
