rows["60:1443517953"]="계속 못해 날개가 날려버릴 거야"
rows["60:1446739773"]="상관없어. 어리석은 녀석... 이제 그 대가를 치러라!"
rows["60:1447218671"]="난 이렇게 행복해본 적이 없어"
rows["60:1451770099"]="상처를  ⁇ 고 다시 싸움을 할 시간이야"
