rows["612:2107656904"]="어서 시작해야 할까요?$B$B첫째, 농부 의 생활 은 씨앗 을 심는 것 과 작물 을 채취 하는 것 이다. 당신이 판매 하는 작물 은 요리 에 사용 될 수 있고, 경매 집 에서 팔 수 있으며, 다른 구매자 들 에게 거래 할 수 있다. 또는 육류 와 물고기 를 교환 할 수 있다. 심지어 희귀 한 씨 가 독특한 아이템 을 위해 심어질 수 있는 것 들 을 들어봤습니다. 어쩌면 작은 애완 동물 도 마찬가지 입니다!$B$B그리고 탐구할 수 있는 모든 하프힐이 있습니다. 현지인들과 친구가 되는 가장 좋은 방법은 선물로 주는 것입니다.$B$B항상 들 근처에 할 일이 많고, 추가적인 손은 정말 감사할 것입니다."
rows["614:876190586"]="<기능적으로, 칼레고스는 지평선을 바라보고 있다.>$b$b타레코사... 나에겐 특별해$b$b그녀는 어린 시절, 저는 그녀의 보호와 교육에 책임이 있었습니다. 수천 년 동안 우리는 특별한 유대감을 형성했습니다.$b$b타레코사 는 위대한 운명을 예언 한 특별한 표지 아래 태어났다. 만약 예언들이 사실이라면, 그녀의 생존은 파란 용 비행과 아제로스 자체에 있어서 매우 중요 하다.$b$b우리 둘 사이의 친밀감은 비행의 잔여에 잘 알려져 있습니다."
rows["615:97331734"]="하카르는 많은 이름으로 알려져 있습니다. 어떤 사람들은 그를 피 신이라고 부르고 다른 사람들은 그를 단순히 영혼 파기자라고 부르고 있습니다. 제목을 제외하고는 그는 우리 세계에 악의적인 의도를 가진 거대한 힘을 가진 존재입니다.$B$B제 비행은 일찍이 이 성전을 발견하고 슬픔의 습지 아래에 가라앉았습니다. 불행히도, 우리는 아탈라이에게 도움을 줄 것으로 보였는데, 하카르를 불러오기 위한 그들의 노력이 방해받지 않았다고 보였습니다.$B$B혼자서는 그들을 막을 수 없는데, 함께 이 미친 짓을 막을 충분한 시간이 있을지도 모릅니다."
rows["618:78270176"]="메레 목표물은 아스피란트를 기마 공격과 방어에 훈련시킵니다.$B$B메레 목표물에 접근하고 추진 공격으로 타격합니다. 타격의 힘은 종종 목표물을 충분히 다치게합니다. 여기 방어가 시작됩니다.$B$B목표물을 공격하기 전에 적어도 한 층의 디펜드를 가지고 있는지 확인하고 훈련 동안 디펜드를 쌓아 올리고 신선하게 유지하십시오. 그렇지 않으면 당신은 잘 탈락 할 수 있습니다.$B$B실제 마운팅 전투에서도 마찬가지입니다. 공격과 방어의 균형을 맞추고, 모든 기회를 누르며,"
rows["61:1000529321"]="대부인겨울은 오그리마까지 와이버너의 차밖에 걸리지 않습니다."
