rows["625:550008774"]="저는 에메랄드 드림 안에서 압도적인 부패로 묘사할 수 있는 것을 만났습니다. 끝없는 악몽이 저를 손톱에 붙잡고 내 마음을 찢어 버렸습니다. 저는 그 잡을 수 없었고 제 제자들은 저를 깨우지 못했습니다.$B$B이 부패 는 무엇 이든지, 그것은 우리 세상 에 내 몸 을 통해 들어갔다. 사실 나는 그 의 에너지를 울음 동굴 에 운반 하였고, 그 의 끔찍한 영향 은 그 곳 의 야생 동물 을 혼란 스럽고 배반 된 형태 로 뒤집어 놓았다. 심지어 제 제자 들 도 그 에 영향을 받았으며, 광신 과 야만성 으로 인해 그들의 정신 을 정복 하였고, 뱀 의 형태 를 취하고, 스스로를  ⁇ 의 드루이드 라고 불렀습니다."
rows["625:573219045"]="너무 많지 않네$B$B판다리아 주변 어두운 땅에서 발견할 수 있는 희귀한 보물 다섯 가지가 있습니다. 루비 셔드, 사랑스러운 사과, 자이드 고양이, 블루 페어, 그리고 마쉬 리리.$B$B가방에 그런 물건이 있는 한 여기 누가 받아 들일 수 있는지 알 수 있을 겁니다.$B$B그 중 하나를 찾아서 좋아하는 사람에게 주면, 아마 그들은 당신을 조금 더 좋아할 것입니다. 다섯가지 중에서 모든 사람들이 좋아하는 아이템을 가지고 있기 때문에 사람들에게 그들이 무엇을 선호하는지 알아내기 위해 이야기하십시오.$B$B여기 사람들은 음식을 좋아해요. 누가 안 먹죠? 요리하는 법을 알고 있다면, 그냥 이익을 얻을 수도 있습니다!$B$B선물에 대해 아는 건 다 그런 거예요"
rows["629:1140006350"]="파다리아에서 가장 큰 맥주 공장인 스톰스타우트 브루어리입니다. 모험을 원한다면 여기서 시작하실 수 있습니다.$B$B맥주 마스터는 또한 자연적으로 방황하는 사람들이며 희귀한 재료들을 찾아나 새로운 맥주를 만들어내는 땅을 돌아다니는 것을 볼 수 있습니다.$B$B그러한 맥주 제작자들은 종종 독특한 시나리오에서 발견된다.$B$B맥주를 만드는 Tzu는 그린스톤 마을의 시나리오에서 적으로부터 방어합니다.$B$B맥주 마스터 보는  ⁇ 가 잉고 시나리오에서 열대적인 맛을 찾고 있습니다.$B$B브루마스터 부프는 브루문 페스티벌 시나리오에서 시즌을 축하하고, 브루마스터 블랑시는 A Brewing Storm에서 충격적인 것을 요리합니다."
