rows["646:1193477593"]="10천 년 전, 불타는 군단의 악마가 아제로스 침략했을 때, 고대인들은 필사적 인종과 함께 싸웠다. 고대인들은 다수가 레지옹의 손에 끝을 맞았다. 세나리우스는 그의 아버지 말론의 행동으로 인해 죽었을 수도 있었다.$B$B거대한 사슴은 전투에 뛰어들었고, 그의 발톱은 악마의 두개골에 떨어졌고 그의 모자들은 그들의 불꽃의 육체를 뚫고 있었다.$B$B그리고 무장장사 아르키몬드 (Archimonde) 가 전투장에 갔고, 격렬한 싸움 끝에 마를른을 그의 모자에서 붙잡고...$B$B하지만 세상에 생명이 있는 한, 마롤른 같은 자연의 힘이 정말로 죽을 수 있을까?"
rows["648:361411238"]="수백 년 전 이 땅 은 여전히 야생 의 일부 였으며 해안 에 도달 하는 것 은 위험 한 여행 이었으며, 큰 크레인의 둥지인 크라사랑그 에서 떠돌고 있는 짐승 들 에게 많은 판다렌 이 사라졌다.$B$B그 때, 유명한 사냥꾼 주 롱브로우가 등장하기 전 까지는, 부당한 희생에 지쳐진 주와 그의 아내 린과 아들 포 - 자신들만의 엄청난 사냥꾼들 - 는 야생의 한 모퉁이를 골라서 정착했습니다.$B$B주 는 야생 들 을 완전히 정착 시키고 싶지 않았으나, 많은 사람들이 그렇게 하도록 간청했읍니다. 그의 지혜 로 그는 그 들 이 또한 큰 크레인을 보호 하는 목적 을 가지고 있다는 것을 이해 하였습니다.$B$B그래서 주 주주는 탄생했고, 주 주 경비도 탄생했다."
