rows["67:981518514"]=" ⁇ 는 아주 유용해요. 한 번 팔을 다시 꿰어야 했어요."
rows["67:988922950"]="성모님께서는 신전에 돌아오시라는 소식을 보내셨습니다."
rows["67:991457799"]="육지놈들치곤 생각보다 질기군. 즉흥적으로 가야겠어!"
rows["67:997885791"]="네가 여기 있으면 고블스가 어떻게 느끼지?$b$b-  ⁇ ?"
rows["689:1430474723"]="매력은 다양한 유익한 효과를 가진 물건을 매료하고, 또한 매혹적인 물건을 매료하고 마법의 막대와 오일을 만들 수 있습니다.\010고도로 숙련된 마법사들은 자신들만의 반지를 매료시킬 수 있습니다.\010매혹의 대부분의 원료는 매혹을 통해 수집되어야 합니다. 매혹된 물건은 파괴되는 과정입니다. 이 때문에 직업은 매혹적인 매혹을 유발할 수 있는 매혹적인 매혹적인 물건들을 매혹시킬 수 있기 때문에 매혹된 물건은 매혹적인 물건으로 만들어집니다.\010마법사 는 또한 장막 에 마법 을 넣을 수 있으며, 이 장막 은 나중에 사용 하기 위해 판매되거나 저장 할 수 있다. 장막 및 기타 유용한 장막 재료 는 장막 판매자 로부터 구입 할 수 있다."
rows["68:1008397951"]="계속 잘 해 $p당신 도움으로 우리는 빠른 시간 안에 끝낼 수 있을거야!"
rows["68:1008915286"]="수천 년 동안 새로운 장난감 없이..."
rows["68:101441769"]="다음엔 밀리 와트, 공학대학원 때 데이트했지"
rows["68:1014776075"]="아마도 어딘가에서 죽음을 기다리고 있을 겁니다."
rows["68:1015175501"]="그녀는 용서할 준비가 되어있었다 호드 테라모르의 멸망을 위해"
rows["68:1021281029"]="스톤탈론의 오크들은 더 이상 당신의 분노를 겪지 않을거야, 거칠고 괴물"
rows["68:1025254623"]="이 어두운 시간 속에서 엘룬의 평화로운 빛이 여러분의 영혼을 진정하게 해 주십시오."
rows["68:1028384402"]="%s]는 고백합니다. 가끔은 타우렌 맛이..."
rows["68:1034959002"]="경관님, 저는 당신의 야간 칼을 타고 아스트라나르로 가고 싶습니다."
rows["68:1036964470"]="말 뒷잔등에 등잔 기름이 있소. 그걸 써보시오. 저 망할 녀석들은 불을 싫어하니까!"
rows["68:1039675327"]="전쟁 구역 내부 반구로 가서 보석 만드는 사람들을 찾아보죠"
rows["68:1041964091"]="걷기 쉬운 상자?"
rows["68:104597004"]="난 단순한 타우렌이야. 베이인과 나는 오랫동안 친구였어."
rows["68:1053383179"]="해적들을 돌봐줄게, 하지만 먼저 용기를 줘"
rows["68:1058440137"]="그들은 피 엘프들이 훔친 유물을 연구하고 있습니다."
rows["68:1081501502"]="세계 기둥의 중간 조각을 가져갈 수 있도록 하겠습니다."
rows["68:1089014276"]="지금 샤도파나 군대에 있어요."
rows["68:1089028575"]="사우로크가 보물들을 가지고 숨겨진 계단으로 내려갑니다!"
rows["68:1091439202"]="오래전부터 맛본 적이 없어서, 이 음식이 딱 맞을 거야"
rows["68:1096165411"]="아니, 토니, 나간게, 나중에 데이트 할 수 있어!"
rows["68:1097620613"]="우리 목숨을 빼앗을 수 있지만... 절대..."
rows["68:1106464439"]="한 번 더 내 드레이크에 악기를 쏘면 난 네 비참한 피부를  ⁇ 어 버릴 거야!"
rows["68:1107914319"]="칼에 두려워하지 마, 헐링, 네가 잡는 게 양고기야!"
rows["68:110805084"]="늙고 어리석은 마녀 같으니... 너희 둘 다 차지할 수 있는데 내가 그럴 이유가 있나?"
rows["68:111626395"]="누가 그랜드 포먼의 탑에 들어갈 만큼 어리석을까?"
rows["68:1121679171"]="다 다크스피어는 다 잔다라리의 계획과 아무 상관이 없다."
